INSERT INTO problem.problems (problem_id, slug, title, difficulty, status, author_user_id, accepted_count, attempts_count, published_at, created_at, updated_at) VALUES ('73e9fc6e-f757-4136-88b5-4d1467b34357', 'cf-2038-n', 'Fixing the Expression', 'EASY', 'PUBLISHED', NULL, 0, 0, NOW(), NOW(), NOW());
INSERT INTO problem.problem_versions (problem_version_id, problem_id, version_number, statement, input_spec, output_spec, checker_type, time_limit_ms, memory_limit_kb, output_limit_bytes, active, created_at) VALUES ('e63173f9-0ec6-4663-9a43-cf3b1ef51f99', '73e9fc6e-f757-4136-88b5-4d1467b34357', 1, 'An expression is a string consisting of three characters, where the first and the last characters are digits (from $$$0$$$ to $$$9$$$), and the middle character is a comparison symbol (<, = or >).

An expression is true if the comparison symbol matches the digits (for example, if the first digit is strictly less than the last digit, the comparison symbol should be <).

For example, the expressions 1<3, 4>2, 0=0 are true, while 5>5, 7<3 are not.

You are given a string $$$s$$$, which is an expression. Change as few characters as possible so that $$$s$$$ becomes a true expression. Note that if $$$s$$$ is already true, you should leave it as it is.

Input:
The first line contains one integer $$$t$$$ ($$$1 \le t \le 300$$$) — the number of test cases.

Each test case consists of one line containing the string $$$s$$$ ($$$|s| = 3$$$, the first and the last characters of $$$s$$$ are digits, the second character is a comparison symbol).

Output:
For each test case, print a string consisting of $$$3$$$ characters — a true expression which can be obtained by changing as few characters as possible in $$$s$$$. If there are multiple answers, print any of them.', 'The first line contains one integer $$$t$$$ ($$$1 \le t \le 300$$$) — the number of test cases.

Each test case consists of one line containing the string $$$s$$$ ($$$|s| = 3$$$, the first and the last characters of $$$s$$$ are digits, the second character is a comparison symbol).', 'For each test case, print a string consisting of $$$3$$$ characters — a true expression which can be obtained by changing as few characters as possible in $$$s$$$. If there are multiple answers, print any of them.', 'STANDARD', 2000, 524288, 65536, true, NOW());
