INSERT INTO problem.problems (problem_id, slug, title, difficulty, status, author_user_id, accepted_count, attempts_count, published_at, created_at, updated_at) VALUES ('d4892ed3-a3ff-4bf1-af29-b5ec179cdcf9', 'cf-2009-b', 'osu!mania', 'EASY', 'PUBLISHED', NULL, 0, 0, NOW(), NOW(), NOW());
INSERT INTO problem.problem_versions (problem_version_id, problem_id, version_number, statement, input_spec, output_spec, checker_type, time_limit_ms, memory_limit_kb, output_limit_bytes, active, created_at) VALUES ('087cbac3-f87e-4701-accf-a67c36cbd8a5', 'd4892ed3-a3ff-4bf1-af29-b5ec179cdcf9', 1, 'You are playing your favorite rhythm game, osu!mania. The layout of your beatmap consists of $$$n$$$ rows and $$$4$$$ columns. Because notes at the bottom are closer, you will process the bottommost row first and the topmost row last. Each row will contain exactly one note, represented as a ''#''.

For each note $$$1, 2, \dots, n$$$, in the order of processing, output the column in which the note appears.

Input:
The first line contains $$$t$$$ ($$$1 \leq t \leq 100$$$) — the number of test cases.

For each test case, the first line contains $$$n$$$ ($$$1 \leq n \leq 500$$$) — the number of rows of the beatmap.

The following $$$n$$$ lines contain $$$4$$$ characters. The $$$i$$$-th line represents the $$$i$$$-th row of the beatmap from the top. It is guaranteed that the characters are either ''.'' or ''#'', and exactly one of the characters is ''#''.

It is guaranteed that the sum of $$$n$$$ over all test cases does not exceed $$$500$$$.

Output:
For each test case, output $$$n$$$ integers on a new line, the column that the $$$i$$$-th note appears in for all $$$i$$$ from $$$1$$$ to $$$n$$$.', 'The first line contains $$$t$$$ ($$$1 \leq t \leq 100$$$) — the number of test cases.

For each test case, the first line contains $$$n$$$ ($$$1 \leq n \leq 500$$$) — the number of rows of the beatmap.

The following $$$n$$$ lines contain $$$4$$$ characters. The $$$i$$$-th line represents the $$$i$$$-th row of the beatmap from the top. It is guaranteed that the characters are either ''.'' or ''#'', and exactly one of the characters is ''#''.

It is guaranteed that the sum of $$$n$$$ over all test cases does not exceed $$$500$$$.', 'For each test case, output $$$n$$$ integers on a new line, the column that the $$$i$$$-th note appears in for all $$$i$$$ from $$$1$$$ to $$$n$$$.', 'STANDARD', 1000, 262144, 65536, true, NOW());
