INSERT INTO problem.problems (problem_id, slug, title, difficulty, status, author_user_id, accepted_count, attempts_count, published_at, created_at, updated_at) VALUES ('99ac0512-99df-49cb-95b0-34e00a30cad7', 'cf-2000-e', 'Photoshoot for Gorillas', 'MEDIUM', 'PUBLISHED', NULL, 0, 0, NOW(), NOW(), NOW());
INSERT INTO problem.problem_versions (problem_version_id, problem_id, version_number, statement, input_spec, output_spec, checker_type, time_limit_ms, memory_limit_kb, output_limit_bytes, active, created_at) VALUES ('fbfc117e-8cbf-41cf-a88e-88b474d09f03', '99ac0512-99df-49cb-95b0-34e00a30cad7', 1, 'You really love gorillas, so you decided to organize a photoshoot for them. Gorillas live in the jungle. The jungle is represented as a grid of $$$n$$$ rows and $$$m$$$ columns. $$$w$$$ gorillas agreed to participate in the photoshoot, and the gorilla with index $$$i$$$ ($$$1 \le i \le w$$$) has a height of $$$a_i$$$. You want to place all the gorillas in the cells of the grid such that there is no more than one gorilla in each cell.

The spectacle of the arrangement is equal to the sum of the spectacles of all sub-squares of the grid with a side length of $$$k$$$.

The spectacle of a sub-square is equal to the sum of the heights of the gorillas in it.

From all suitable arrangements, choose the arrangement with the maximum spectacle.

Input:
The first line contains an integer $$$t$$$ ($$$1 \le t \le 10^3$$$) — the number of test cases.

The descriptions of the test cases follow.

The first line contains integers $$$n$$$, $$$m$$$, $$$k$$$ ($$$1 \le n, m \le 2 \cdot 10^5$$$, $$$1 \le n \cdot m \le 2 \cdot 10^5$$$, $$$1 \le k \le \min(n, m)$$$) — the dimensions of the grid and the side length of the square.

The second line contains an integer $$$w$$$ ($$$1 \le w \le n \cdot m$$$) — the number of gorillas.

The third line contains $$$w$$$ integers $$$a_1, a_2, \ldots, a_w$$$ ($$$1 \le a_i \le 10^9$$$) — the heights of the gorillas.

It is guaranteed that the sum of $$$n \cdot m$$$ across all test cases does not exceed $$$2 \cdot 10^5$$$. The same guarantee applies to $$$w$$$.

Output:
For each test case, output a single integer — the maximum spectacle of a suitable arrangement.

Note:
In the first test case of the first input set, the spectacle of the following sub-squares is summed:

Yellow color corresponds to the sub-squares, green — to the rest of the grid squares.

The picture shows the optimal arrangement of the gorillas. The spectacle of the arrangement is $$$4 + 4 + 3 + 3 + 4 + 3 = 21$$$.', 'The first line contains an integer $$$t$$$ ($$$1 \le t \le 10^3$$$) — the number of test cases.

The descriptions of the test cases follow.

The first line contains integers $$$n$$$, $$$m$$$, $$$k$$$ ($$$1 \le n, m \le 2 \cdot 10^5$$$, $$$1 \le n \cdot m \le 2 \cdot 10^5$$$, $$$1 \le k \le \min(n, m)$$$) — the dimensions of the grid and the side length of the square.

The second line contains an integer $$$w$$$ ($$$1 \le w \le n \cdot m$$$) — the number of gorillas.

The third line contains $$$w$$$ integers $$$a_1, a_2, \ldots, a_w$$$ ($$$1 \le a_i \le 10^9$$$) — the heights of the gorillas.

It is guaranteed that the sum of $$$n \cdot m$$$ across all test cases does not exceed $$$2 \cdot 10^5$$$. The same guarantee applies to $$$w$$$.', 'For each test case, output a single integer — the maximum spectacle of a suitable arrangement.', 'STANDARD', 2000, 262144, 65536, true, NOW());
