INSERT INTO problem.problems (problem_id, slug, title, difficulty, status, author_user_id, accepted_count, attempts_count, published_at, created_at, updated_at) VALUES ('43649220-4c21-490c-86d9-0470abee7827', 'cf-2037-g', 'Natlan Exploring', 'HARD', 'PUBLISHED', NULL, 0, 0, NOW(), NOW(), NOW());
INSERT INTO problem.problem_versions (problem_version_id, problem_id, version_number, statement, input_spec, output_spec, checker_type, time_limit_ms, memory_limit_kb, output_limit_bytes, active, created_at) VALUES ('257c0dbc-c27f-42dc-acda-a1f66bd14fd5', '43649220-4c21-490c-86d9-0470abee7827', 1, 'You are exploring the stunning region of Natlan! This region consists of $$$n$$$ cities, and each city is rated with an attractiveness $$$a_i$$$. A directed edge exists from City $$$i$$$ to City $$$j$$$ if and only if $$$i < j$$$ and $$$\gcd(a_i,a_j)\neq 1$$$, where $$$\gcd(x, y)$$$ denotes the greatest common divisor (GCD) of integers $$$x$$$ and $$$y$$$.

Starting from City $$$1$$$, your task is to determine the total number of distinct paths you can take to reach City $$$n$$$, modulo $$$998\,244\,353$$$. Two paths are different if and only if the set of cities visited is different.

Input:
The first line contains an integer $$$n$$$ ($$$2 \leq n \leq 2 \cdot 10^5$$$) — the number of cities.

The second line contains $$$n$$$ integers $$$a_1, a_2, \ldots, a_n$$$ ($$$2 \leq a_i \leq 10^6$$$) — the attractiveness of each city.

Output:
Output the total number of distinct paths you can take to reach City $$$n$$$, modulo $$$998\,244\,353$$$.

Note:
In the first example, the five paths are the following:

- City $$$1\rightarrow$$$ City $$$5$$$
- City $$$1\rightarrow$$$ City $$$2\rightarrow$$$ City $$$5$$$
- City $$$1\rightarrow$$$ City $$$2\rightarrow$$$ City $$$3\rightarrow$$$ City $$$5$$$
- City $$$1\rightarrow$$$ City $$$2\rightarrow$$$ City $$$4\rightarrow$$$ City $$$5$$$
- City $$$1\rightarrow$$$ City $$$4\rightarrow$$$ City $$$5$$$

In the second example, the two paths are the following:

- City $$$1\rightarrow$$$ City $$$3\rightarrow$$$ City $$$5$$$
- City $$$1\rightarrow$$$ City $$$2\rightarrow$$$ City $$$3\rightarrow$$$ City $$$5$$$', 'The first line contains an integer $$$n$$$ ($$$2 \leq n \leq 2 \cdot 10^5$$$) — the number of cities.

The second line contains $$$n$$$ integers $$$a_1, a_2, \ldots, a_n$$$ ($$$2 \leq a_i \leq 10^6$$$) — the attractiveness of each city.', 'Output the total number of distinct paths you can take to reach City $$$n$$$, modulo $$$998\,244\,353$$$.', 'STANDARD', 4000, 262144, 65536, true, NOW());
