INSERT INTO problem.problems (problem_id, slug, title, difficulty, status, author_user_id, accepted_count, attempts_count, published_at, created_at, updated_at) VALUES ('de2dd692-ae75-459e-8194-e73b300823e6', 'cf-2036-a', 'Quintomania', 'EASY', 'PUBLISHED', NULL, 0, 0, NOW(), NOW(), NOW());
INSERT INTO problem.problem_versions (problem_version_id, problem_id, version_number, statement, input_spec, output_spec, checker_type, time_limit_ms, memory_limit_kb, output_limit_bytes, active, created_at) VALUES ('139c882e-3124-4ba0-98b1-7bf0d0b5e095', 'de2dd692-ae75-459e-8194-e73b300823e6', 1, 'Boris Notkin composes melodies. He represents them as a sequence of notes, where each note is encoded as an integer from $$$0$$$ to $$$127$$$ inclusive. The interval between two notes $$$a$$$ and $$$b$$$ is equal to $$$|a - b|$$$ semitones.

Boris considers a melody perfect if the interval between each two adjacent notes is either $$$5$$$ semitones or $$$7$$$ semitones.

After composing his latest melodies, he enthusiastically shows you his collection of works. Help Boris Notkin understand whether his melodies are perfect.

Input:
The first line contains an integer $$$t$$$ ($$$1 \leq t \leq 1000$$$) — the number of melodies.

Each melody is described by two lines.

The first line contains an integer $$$n$$$ ($$$2 \leq n \leq 50$$$) — the number of notes in the melody.

The second line contains $$$n$$$ integers $$$a_{1}, a_{2}, \dots, a_{n}$$$ ($$$0 \leq a_{i} \leq 127$$$) — the notes of the melody.

Output:
For each melody, output "YES", if it is perfect; otherwise, output "NO".

You can output the answer in any case (upper or lower). For example, the strings "yEs", "yes", "Yes", and "YES" will be recognized as positive responses.', 'The first line contains an integer $$$t$$$ ($$$1 \leq t \leq 1000$$$) — the number of melodies.

Each melody is described by two lines.

The first line contains an integer $$$n$$$ ($$$2 \leq n \leq 50$$$) — the number of notes in the melody.

The second line contains $$$n$$$ integers $$$a_{1}, a_{2}, \dots, a_{n}$$$ ($$$0 \leq a_{i} \leq 127$$$) — the notes of the melody.', 'For each melody, output "YES", if it is perfect; otherwise, output "NO".

You can output the answer in any case (upper or lower). For example, the strings "yEs", "yes", "Yes", and "YES" will be recognized as positive responses.', 'STANDARD', 1000, 262144, 65536, true, NOW());
