INSERT INTO problem.problems (problem_id, slug, title, difficulty, status, author_user_id, accepted_count, attempts_count, published_at, created_at, updated_at) VALUES ('3865e952-6050-41ec-829e-e19118a4d5cf', 'cf-2044-b', 'Normal Problem', 'EASY', 'PUBLISHED', NULL, 0, 0, NOW(), NOW(), NOW());
INSERT INTO problem.problem_versions (problem_version_id, problem_id, version_number, statement, input_spec, output_spec, checker_type, time_limit_ms, memory_limit_kb, output_limit_bytes, active, created_at) VALUES ('fe4f4505-208d-4d0f-a86a-5606a2c44993', '3865e952-6050-41ec-829e-e19118a4d5cf', 1, 'A string consisting of only characters ''p'', ''q'', and ''w'' is painted on a glass window of a store. Ship walks past the store, standing directly in front of the glass window, and observes string $$$a$$$. Ship then heads inside the store, looks directly at the same glass window, and observes string $$$b$$$.

Ship gives you string $$$a$$$. Your job is to find and output $$$b$$$.

Input:
The first line contains an integer $$$t$$$ ($$$1 \leq t \leq 100$$$) — the number of test cases.

The only line of each test case contains a string $$$a$$$ ($$$1 \leq |a| \leq 100$$$) — the string Ship observes from outside the store. It is guaranteed that $$$a$$$ only contains characters ''p'', ''q'', and ''w''.

Output:
For each test case, output string $$$b$$$, the string Ship observes from inside the store, on a new line.', 'The first line contains an integer $$$t$$$ ($$$1 \leq t \leq 100$$$) — the number of test cases.

The only line of each test case contains a string $$$a$$$ ($$$1 \leq |a| \leq 100$$$) — the string Ship observes from outside the store. It is guaranteed that $$$a$$$ only contains characters ''p'', ''q'', and ''w''.', 'For each test case, output string $$$b$$$, the string Ship observes from inside the store, on a new line.', 'STANDARD', 1000, 262144, 65536, true, NOW());
